// Generated by wikiloop build from the core on-call screen; edit wikiloop.toml [oncall], not this file.
//
// The screen only draws: every problem in state.json carries a `view` the engine wrote (label,
// what, error, links), and config.ts says which sections the pane has and how the line counts.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import {
  CHRONIC_AFTER_MS,
  COMMAND,
  DEFAULT_ENV,
  DEFAULT_INTERVAL_MS,
  FLOOR,
  LINE_LABEL,
  LOUD,
  NEW_WINDOW_MS,
  OFF_AFTER_MS,
  RESOLVED_KEPT_MS,
  SECTIONS,
  SEVERITIES,
  STALE_SLACK_MS,
  START_GUARD_MS,
  START_PROMPT,
  STATE_PATH,
  STATE_UNDER_HOME,
  STOP_PROMPT,
  TIER_RANK,
  TITLE,
} from './config'
import type { Item, ItemLink, Section, SectionDef, Snapshot } from './state'

const PANE = 'oncall'
const PANE_PADDING_X = 2
const POLL_MS = 15_000
const SUBMIT_DELAY_MS = 100

const DEFAULT_COLUMNS = 80
const LINE_SLACK = 4 // the row's indent and a glyph such as ⚠ that some terminals draw two cells wide
const MAX_NAMES = 3
const HINT_GAP = '   '

const snapshot = atom({ plugin: 'acme-wiki', key: 'snapshot' } as const, null)
const autoOpened = atom({ plugin: 'acme-wiki', key: 'autoOpened' } as const, false)
const started = atom({ plugin: 'acme-wiki', key: 'startedMs' } as const, 0)
const off = atom({ plugin: 'acme-wiki', key: 'off' } as const, false)

const RANK: Record<string, number> = Object.fromEntries(SEVERITIES.map(s => [s.name, s.rank]))
const COLOR: Record<string, string> = Object.fromEntries(SEVERITIES.map(s => [s.name, s.color]))

export type Problem = {
  id: string
  scope: string
  component: string
  severity: string
  tier: string
  env: string
  status: string
  first_seen: number
  resolved_at?: number
  view?: { label: string; what: string; error: string; links: ItemLink[]; tier: string }
}

function age(ms: number): string {
  const minutes = ms / 60_000
  if (minutes < 60) return `${Math.round(minutes)}m`

  const hours = minutes / 60
  if (hours < 24) return `${Math.round(hours)}h`

  return `${Math.round(hours / 24)}d`
}

function hhmm(ms: number): string {
  return new Date(ms).toISOString().slice(11, 16) + 'Z'
}

function colorOf(name: string): string | undefined {
  return COLOR[name] || undefined
}

function rankOf(p: Problem): number {
  return RANK[p.severity] ?? 0
}

// a pod address from a rule's generator URL is no link a browser opens
function isWebLink(href: string | undefined): boolean {
  return href?.startsWith('https://') ?? false
}

function item(p: Problem, ageText: string, isNew: boolean): Item {
  const view = p.view

  return {
    id: p.id,
    label: view?.label || p.id,
    severity: p.severity,
    tier: view?.tier ?? '',
    what: view?.what ?? '',
    error: view?.error ?? '',
    age: ageText,
    isNew,
    links: (view?.links ?? []).filter(link => isWebLink(link.href)),
  }
}

function byImportance(a: Problem, b: Problem): number {
  const severity = rankOf(b) - rankOf(a)
  if (severity) return severity

  const tier = (TIER_RANK[b.tier] ?? 0) - (TIER_RANK[a.tier] ?? 0)
  if (tier) return tier

  const isOtherEnv = (p: Problem) => Number(p.env !== '-' && p.env !== DEFAULT_ENV)
  const env = isOtherEnv(a) - isOtherEnv(b)
  if (env) return env

  return a.first_seen - b.first_seen
}

/** The pane's filter, the same as the engine's report: status, severity range, chronic, new. */
function matches(def: SectionDef, p: Problem, flags: { isChronic: boolean; isNew: boolean }, belowFloor: boolean): boolean {
  if (p.status !== def.status) return false

  const isBelow = def.minSeverity !== '' && rankOf(p) < (RANK[def.minSeverity] ?? 0)
  if (isBelow !== belowFloor) return false
  if (def.maxSeverity !== '' && rankOf(p) > (RANK[def.maxSeverity] ?? 0)) return false

  const rules: [SectionDef['chronic'], boolean][] = [[def.chronic, flags.isChronic], [def.isNew, flags.isNew]]
  for (const [rule, flag] of rules) {
    if (rule === 'only' && !flag) return false
    if (rule === 'exclude' && flag) return false
  }

  return true
}

export function build(problems: Problem[], updatedMs: number, nowMs: number, intervalMs = DEFAULT_INTERVAL_MS): Snapshot {
  const sorted = [...problems].sort(byImportance)
  const open = sorted.filter(p => p.status === 'open')

  const openFor = (p: Problem) => nowMs - p.first_seen * 1000
  const isChronic = (p: Problem) => p.status === 'open' && openFor(p) >= CHRONIC_AFTER_MS
  const isNew = (p: Problem) => p.status === 'open' && rankOf(p) >= (RANK[FLOOR] ?? 0) && openFor(p) < NEW_WINDOW_MS
  const isKept = (p: Problem) => p.status !== 'resolved' || nowMs - (p.resolved_at ?? 0) * 1000 < RESOLVED_KEPT_MS
  const flagsOf = (p: Problem) => ({ isChronic: isChronic(p), isNew: isNew(p) })

  const itemOf = (p: Problem) =>
    p.status === 'resolved' ? item(p, hhmm((p.resolved_at ?? 0) * 1000), false) : item(p, age(openFor(p)), isNew(p))

  const kept = sorted.filter(isKept)
  const sections: Section[] = SECTIONS.map(def => {
    const members = kept.filter(p => matches(def, p, flagsOf(p), false))
    const shown = def.limit > 0 ? members.slice(0, def.limit) : members
    const folded = def.foldBelow ? kept.filter(p => matches(def, p, flagsOf(p), true)).length : 0
    const below = SEVERITIES.filter(s => s.rank < (RANK[def.minSeverity] ?? 0)).map(s => s.name)

    return {
      title: def.title,
      status: def.status,
      color: def.color,
      style: def.style,
      empty: def.empty,
      count: members.length,
      items: shown.map(itemOf),
      more: members.length - shown.length,
      folded,
      foldedLabel: below.join('/'),
    }
  })

  const counts: Record<string, number> = Object.fromEntries(SEVERITIES.map(s => [s.name, 0]))
  for (const p of open) {
    if (p.severity in counts) counts[p.severity] = (counts[p.severity] ?? 0) + 1
  }

  const staleMs = nowMs - updatedMs
  const staleAfterMs = 2 * intervalMs + STALE_SLACK_MS

  return {
    updatedMs,
    staleMinutes: staleMs > staleAfterMs ? Math.floor(staleMs / 60_000) : 0,
    counts,
    fresh: open.filter(isNew).map(itemOf),
    loud: open.filter(p => rankOf(p) >= (RANK[LOUD] ?? 0)).map(itemOf),
    sections,
  }
}

export type Segment = { text: string; color?: string; bold?: boolean; dim?: boolean }

const SEPARATOR: Segment = { text: ' │ ', dim: true }
const DOT: Segment = { text: ' · ', dim: true }

function widthOf(segments: Segment[]): number {
  return segments.reduce((sum, s) => sum + s.text.length, 0)
}

/** As many names as fit in `room`, at most MAX_NAMES, then `+N` for the rest; '' when not one fits. */
function fitNames(names: string[], room: number): string {
  for (let shown = Math.min(names.length, MAX_NAMES); shown > 0; shown--) {
    const rest = names.length - shown
    const text = names.slice(0, shown).join(', ') + (rest ? ` +${rest}` : '')

    if (text.length <= room) return text
  }

  return ''
}

/**
 * The line under the prompt, cut to `columns` so it never wraps. The counts always show;
 * the loud names, the new names and the engine's hint take what room is left, in that order.
 */
export function lineOf(snap: Snapshot, columns: number, hint: string): { segments: Segment[]; hint: string } {
  const loudRank = RANK[LOUD] ?? 0
  const floorRank = RANK[FLOOR] ?? 0
  const isLoud = snap.loud.length > 0

  const segments: Segment[] = [{ text: `${LINE_LABEL} ${hhmm(snap.updatedMs)}`, bold: true }]
  if (snap.staleMinutes > 0) segments.push({ text: ` ⚠ stale ${snap.staleMinutes}m`, color: 'error', bold: true })
  segments.push(SEPARATOR)

  // above the loud severity a count shows only when something is there
  for (const s of SEVERITIES.filter(s => s.rank > loudRank)) {
    const count = snap.counts[s.name] ?? 0
    if (count > 0) segments.push({ text: `${count} ${s.name} · `, color: colorOf(s.name), bold: true })
  }

  const quieter = SEVERITIES.filter(s => s.rank < loudRank && s.rank >= floorRank).map(s => {
    const count = snap.counts[s.name] ?? 0
    return { text: `${count} ${s.name}`, color: count ? colorOf(s.name) : undefined } as Segment
  })
  const tail = quieter.flatMap((s, i) => (i === 0 ? [SEPARATOR, s] : [DOT, s]))

  const loudCount = `${snap.counts[LOUD] ?? 0} ${LOUD}`
  let room = columns - LINE_SLACK - widthOf(segments) - loudCount.length - widthOf(tail)

  const names = fitNames(snap.loud.map(it => it.label), room - 2)
  const loud: Segment = { text: names ? `${loudCount}: ${names}` : loudCount, color: isLoud ? colorOf(LOUD) : undefined }
  room -= loud.text.length - loudCount.length
  segments.push(loud, ...tail)

  if (snap.fresh.length > 0) {
    const prefix = ' │ new: '
    const freshNames = fitNames(snap.fresh.map(it => it.label), room - prefix.length)
    const text = freshNames ? `${prefix}${freshNames}` : ` │ ${snap.fresh.length} new`

    if (text.length <= room) {
      segments.push({ text, color: 'error', bold: true })
      room -= text.length
    }
  }

  const hintFits = hint !== '' && HINT_GAP.length + hint.length <= room

  return { segments, hint: hintFits ? hint : '' }
}

/** The line between the command and the watch's first cycle, which has nothing to count yet. */
export function startingLineOf(columns: number, hint: string): { segments: Segment[]; hint: string } {
  const segments: Segment[] = [{ text: LINE_LABEL, bold: true }, SEPARATOR, { text: 'starting, waiting for the first cycle', dim: true }]

  const room = columns - LINE_SLACK - widthOf(segments)
  const hintFits = hint !== '' && HINT_GAP.length + hint.length <= room

  return { segments, hint: hintFits ? hint : '' }
}

/** A click on the line: shows the pane, or closes it when it is the one shown. */
async function togglePane($: EngineInterface): Promise<void> {
  const panes = await $.ui.panes()
  const isShown = panes.some(pane => pane.id === PANE && pane.isShown && pane.isPlaced)

  if (isShown) {
    await $.ui.close({ id: PANE })
    return
  }

  await $.ui.open({ id: PANE, title: TITLE, closeOnEscape: true })
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'oncall',
      description: `Start the ${LINE_LABEL} watch, or open or close its pane (/${COMMAND} off stops the watch and hides its line)`,
    })

    // a pinned status from an earlier load of this mod would outlive it
    $.ui.status(undefined)

    const home = await $.env.get('HOME')
    const statePath = STATE_UNDER_HOME ? `${home}/${STATE_PATH}` : STATE_PATH
    let lastJson = ''

    const poll = async () => {
      const nowMs = await $.clock.now()
      let snap: Snapshot | null = null

      try {
        const stat = await $.fs.stat(statePath)

        if (stat.kind === 'file' && nowMs - stat.mtimeMs < OFF_AFTER_MS) {
          const state = JSON.parse(await $.fs.read(statePath))
          const problems = Object.values(state.problems ?? {}) as Problem[]
          const intervalMs = Number(state.interval) * 1000 || DEFAULT_INTERVAL_MS
          snap = build(problems, stat.mtimeMs, nowMs, intervalMs)
        }
      } catch {
        snap = null
      }

      const startedMs = await read($, started)
      if (startedMs > 0) {
        const hasCycle = snap !== null && snap.updatedMs >= startedMs
        const isOverdue = nowMs - startedMs >= START_GUARD_MS

        if (hasCycle) {
          await update($, started, () => 0)
        } else if (isOverdue) {
          await update($, started, () => 0)
          $.ui.toast(`The ${LINE_LABEL} watch wrote no cycle in ${START_GUARD_MS / 60_000}m; /${COMMAND} starts it again.`)
        }
      }

      // the ages move every minute; redraw only when what is drawn changed
      const json = JSON.stringify(snap)
      if (json === lastJson) return
      lastJson = json
      await update($, snapshot, () => snap)

      // open once per session when a watch runs; afterwards only the command or the line opens it
      const opened = await read($, autoOpened)
      const isOff = await read($, off)
      const isLive = snap !== null && snap.staleMinutes === 0
      if (isLive && !opened && !isOff) {
        await update($, autoOpened, () => true)
        await $.ui.open({ id: PANE, title: TITLE, closeOnEscape: true })
      }
    }

    void poll()
    $.clock.every(POLL_MS, () => void poll())

    return next(e)
  })

  // a literal matcher, so the host knows which command this hook answers before it runs
  on('command.run', { command: 'oncall' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    const panes = await $.ui.panes()
    const isOpen = panes.some(pane => pane.id === PANE)

    if (arg === 'close') {
      if (isOpen) await $.ui.close({ id: PANE })

      return { text: `${TITLE} pane closed.` }
    }

    const snap = await read($, snapshot)
    const startedMs = await read($, started)

    if (arg === 'off') {
      if (isOpen) await $.ui.close({ id: PANE })

      const isWatched = snap !== null || startedMs > 0
      await update($, off, () => true)
      await update($, started, () => 0)

      if (!isWatched) return { text: `${TITLE} off: no line, no pane. /${COMMAND} turns it on again.` }

      $.clock.after(SUBMIT_DELAY_MS, () => void $.prompt.submit({ text: STOP_PROMPT }))

      return { text: `${TITLE} off: no line, no pane, and Claude stops the watch. /${COMMAND} turns it on again.` }
    }

    await update($, off, () => false)

    const isLive = snap !== null && snap.staleMinutes === 0

    if (!isLive) {
      const nowMs = await $.clock.now()

      // a second command before the first cycle must not start a second watcher
      const isStarting = startedMs > 0 && nowMs - startedMs < START_GUARD_MS
      if (isStarting) {
        return { text: `The ${LINE_LABEL} watch is starting; the pane opens after its first cycle.` }
      }

      await update($, started, () => nowMs)
      await update($, autoOpened, () => false)

      // the engine refuses a submit from this hook, as its turn would wait on this command; a timer fires after it ends
      $.clock.after(SUBMIT_DELAY_MS, () => void $.prompt.submit({ text: START_PROMPT }))

      return { text: `No live ${LINE_LABEL} watch: Claude starts one under Monitor. The line under the prompt says so until its first cycle, then the pane opens.` }
    }

    if (isOpen) {
      await $.ui.close({ id: PANE })

      return { text: `${TITLE} pane closed.` }
    }

    await $.ui.open({ id: PANE, title: TITLE, closeOnEscape: true })

    return { text: `${TITLE} pane opened. /${COMMAND} again or Esc closes it.` }
  })

  // the line under the prompt: the counts, a click opens or closes the pane; the engine's hint follows when it fits
  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    if (await read($, off)) return next(e)

    const snap = await read($, snapshot)
    const isStarting = (await read($, started)) > 0
    if (!snap && !isStarting) return next(e)

    const { Box, Button, Text } = $.ui.resolve(e)
    const columns = e.viewport?.columns ?? DEFAULT_COLUMNS

    // a stale report from an earlier watch gives way to the start of a new one
    const line = snap && !isStarting ? lineOf(snap, columns, e.props.hint) : startingLineOf(columns, e.props.hint)

    // the engine's own drawing keeps its pills (a PR link) live; `hint` is only their text
    const engineLine = line.hint ? await next(e) : null

    return (
      <Box>
        <Button key="oncall-status" plain onPress={() => void togglePane($)}>
          <Text wrap="truncate-end">
            {line.segments.map((s, i) => (
              <Text key={`segment-${i}`} color={s.color} bold={s.bold} dimColor={s.dim}>{s.text}</Text>
            ))}
          </Text>
        </Button>
        {engineLine && <Box marginLeft={HINT_GAP.length}>{engineLine}</Box>}
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Link, Text } = $.ui.resolve(e)
    const snap = await read($, snapshot)
    const isStarting = (await read($, started)) > 0

    if (!snap && isStarting) {
      return (
        <Box paddingX={PANE_PADDING_X}>
          <Text dimColor>The {LINE_LABEL} watch is starting; the report follows its first cycle.</Text>
        </Box>
      )
    }

    if (!snap) {
      return (
        <Box flexDirection="column" paddingX={PANE_PADDING_X}>
          <Text dimColor>No {LINE_LABEL} watch has run in the last {age(OFF_AFTER_MS)}.</Text>
          <Text dimColor>Start one with /{COMMAND}.</Text>
        </Box>
      )
    }

    const loudRank = RANK[LOUD] ?? 0

    // a problem: what and where, then why, then where to look
    const full = (it: Item) => (
      <Box key={it.id} flexDirection="column" marginTop={1}>
        <Text wrap="truncate-end">
          <Text color={colorOf(it.severity)}>● </Text>
          <Text bold>{it.label}</Text>
          {it.isNew && <Text color="error" bold> NEW</Text>}
          <Text dimColor>  {[it.tier, it.age].filter(Boolean).join(' · ')}</Text>
        </Text>
        <Text wrap="truncate-end">  {it.what}</Text>
        {it.error && <Text dimColor wrap="truncate-end">  {it.error}</Text>}
        {it.links.length > 0 && (
          <Text dimColor wrap="truncate-end">
            {'  '}
            {it.links.map((link, i) => (
              <Text key={link.href}>
                {i > 0 && ' · '}
                <Link href={link.href}>{link.label}</Link>
              </Text>
            ))}
          </Text>
        )}
      </Box>
    )

    const compact = (section: Section) => (it: Item) => (
      <Text key={it.id} wrap="truncate-end">
        <Text color={section.color || colorOf(it.severity)}>{section.status === 'resolved' ? '✓ ' : '● '}</Text>
        {it.label}
        <Text dimColor>  {it.age}</Text>
      </Text>
    )

    const body = (section: Section) => {
      if (section.style === 'inline') {
        return <Text dimColor wrap="wrap">{section.items.map(it => `${it.label} ${it.age}`).join(' · ')}</Text>
      }

      return section.items.map(section.style === 'full' ? full : compact(section))
    }

    const drawSection = (section: Section, index: number) => {
      const isEmpty = section.count === 0
      if (isEmpty && section.empty === '') return null

      return (
        <Box key={`section-${index}`} flexDirection="column">
          <Box marginTop={1}>
            <Text bold color={isEmpty ? undefined : section.color || undefined}>{section.title} ({section.count})</Text>
          </Box>
          {isEmpty ? <Text dimColor>{section.empty}</Text> : body(section)}
          {section.more > 0 && <Text dimColor>  and {section.more} more</Text>}
          {section.folded > 0 && <Text dimColor>  and {section.folded} {section.foldedLabel}</Text>}
        </Box>
      )
    }

    return (
      <Box flexDirection="column" paddingX={PANE_PADDING_X}>
        <Text wrap="truncate-end">
          <Text dimColor>updated {hhmm(snap.updatedMs)}</Text>
          {SEVERITIES.map(s => {
            const count = snap.counts[s.name] ?? 0
            const isStrong = s.rank >= loudRank && count > 0

            return (
              <Text key={s.name}>
                <Text dimColor> · </Text>
                <Text color={isStrong ? colorOf(s.name) : undefined} bold={isStrong} dimColor={!isStrong}>{count} {s.name}</Text>
              </Text>
            )
          })}
        </Text>
        {snap.staleMinutes > 0 && (
          <Text color="error" bold>⚠ watcher stale: last cycle {snap.staleMinutes}m ago</Text>
        )}

        {snap.sections.map(drawSection)}
      </Box>
    )
  })
}
